import pandas as pd, numpy as np, random, os, json, math, itertools, sys, textwrap, collections

# Paths are provided by the system
DATASET_PATH = "chunks_csv/moran_local_2021_waste.csv"
# ADJACENCY_PATH variable already exists in the execution environment
from pathlib import Path, PurePosixPath, PurePath, PureWindowsPath, PosixPath

# Load data
df = pd.read_csv(DATASET_PATH)
adj_df = pd.read_csv(ADJACENCY_PATH)

# Build undirected adjacency list
adjacency = {b: set() for b in df['borough']}
for _, row in adj_df.iterrows():
    b1, b2 = row['borough'], row['neighbor']
    if b1 in adjacency:
        adjacency[b1].add(b2)
    else:
        adjacency[b1] = {b2}
    if b2 in adjacency:
        adjacency[b2].add(b1)
    else:
        adjacency[b2] = {b1}

# Map borough to index and arrays
boroughs = df['borough'].tolist()
index_map = {b: i for i, b in enumerate(boroughs)}
values = df['Waste_value'].values
z = (values - values.mean()) / values.std(ddof=0)  # population std

# Precompute neighbor index lists
neighbor_indices = []
for b in boroughs:
    neighs = [index_map[n] for n in adjacency.get(b, []) if n in index_map]
    neighbor_indices.append(neighs)

# Compute observed Local Moran I
I_obs = np.zeros(len(boroughs))
for i, neighs in enumerate(neighbor_indices):
    if len(neighs) == 0:
        I_obs[i] = np.nan  # Cannot compute without neighbors
    else:
        I_obs[i] = z[i] * sum(z[j] for j in neighs)

print("Observed Local Moran's I values:")
for b, val in zip(boroughs, I_obs):
    print(f"{b}: {val}")

# Permutation test
n_perm = 999
counts = np.zeros(len(boroughs), dtype=int)

for _ in range(n_perm):
    z_perm = np.random.permutation(z)
    for i, neighs in enumerate(neighbor_indices):
        if len(neighs) == 0:
            continue
        I_perm = z_perm[i] * sum(z_perm[j] for j in neighs)
        if abs(I_perm) >= abs(I_obs[i]):
            counts[i] += 1

p_vals = (counts + 1) / (n_perm + 1)

print("\nPermutation p-values:")
for b, p in zip(boroughs, p_vals):
    print(f"{b}: {p}")

# Classify Hot Spot (HH) or Cold Spot (LL)
qualifying = []
for i, b in enumerate(boroughs):
    if np.isnan(I_obs[i]) or p_vals[i] >= 0.05:
        continue  # not significant or no neighbors
    neigh_mean = np.mean([z[j] for j in neighbor_indices[i]]) if neighbor_indices[i] else 0
    if z[i] > 0 and neigh_mean > 0:
        qualifying.append((b, "HH", I_obs[i]))
    elif z[i] < 0 and neigh_mean < 0:
        qualifying.append((b, "LL", I_obs[i]))

# Build FINAL ANSWER line
if qualifying:
    parts = [f"{b} ({cl}, Local Moran I={val:.4f})" for b, cl, val in qualifying]
    final_line = "FINAL ANSWER: " + ", ".join(parts)
else:
    final_line = "FINAL ANSWER: none"

print("\n" + final_line)
